<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { getAdminComplaintPriorityMappings, replaceAdminComplaintPriorityMappings } from '../../api/complaint'
import { confirmDialog } from '../ui/feedback'
import SInput from '../ui/SInput.vue'
import SSelect from '../ui/SSelect.vue'
import SButton from '../ui/SButton.vue'
import SBanner from '../ui/SBanner.vue'

const version=ref(null),rules=ref([]),reason=ref(''),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),unknown=ref(false),pending=ref(null),dirty=ref(false)
const busy=computed(()=>loading.value||saving.value||unknown.value)
let alive=true,sequence=0
const priorityOptions=[1,2,3,4].map(value=>({value,label:value+'级'}))
async function load(){const ticket=++sequence;loading.value=true;error.value='';try{const {data}=await getAdminComplaintPriorityMappings();if(!alive||ticket!==sequence)return;if(!Number.isSafeInteger(data?.version)||!Array.isArray(data?.rules))throw new Error('映射规则响应不完整');version.value=data.version;rules.value=data.rules.map(row=>({...row,priority:Number(row.priority),enabled:!!row.enabled}));dirty.value=false}catch(e){if(alive&&ticket===sequence)error.value=e.message}finally{if(alive&&ticket===sequence)loading.value=false}}
function addRule(){if(busy.value)return;rules.value.push({fault_type:'',impact_scope:'',priority:1,enabled:true});dirty.value=true}
function removeRule(index){if(busy.value)return;rules.value.splice(index,1);dirty.value=true}
function update(){dirty.value=true}
function freeze(){return{version:version.value,operation_id:crypto.randomUUID(),reason:reason.value.trim(),rules:rules.value.map(row=>({fault_type:String(row.fault_type||'').trim(),impact_scope:String(row.impact_scope||'').trim(),priority:Number(row.priority),enabled:!!row.enabled}))}}
async function send(){if(!pending.value||saving.value)return;saving.value=true;unknown.value=false;error.value='';const operation=JSON.parse(JSON.stringify(pending.value));try{const {data}=await replaceAdminComplaintPriorityMappings(operation);if(!alive)return;if(data?.version!==operation.version+1||data?.rules?.length!==operation.rules.length)throw new Error('映射保存回执不完整；请以原操作ID核对');notice.value=`已保存映射版本${data.version}。新规则只影响之后提交的设施报修，历史初始级别不回算。`;reason.value='';pending.value=null;unknown.value=false;dirty.value=false;await load()}catch(e){if(!alive)return;unknown.value=e.status==null||e.status===408||e.status>=500;error.value=unknown.value?'保存结果尚未确认，原版本、规则、理由和操作ID已锁定；使用原操作ID重试核对。':e.message;if(!unknown.value)pending.value=null}finally{if(alive)saving.value=false}}
async function save(){if(busy.value||!dirty.value)return;const body=freeze();if(!body.reason||body.reason.length>1000){error.value='请填写1至1000字变更理由';return}if(body.rules.length>500||body.rules.some(rule=>!rule.fault_type||rule.fault_type.length>100||!rule.impact_scope||rule.impact_scope.length>100||![1,2,3,4].includes(rule.priority))){error.value='请完整填写故障类型、影响范围及1至4级映射；5级由安全规则固定产生';return}pending.value=body;try{await confirmDialog(`保存第${body.version+1}版映射，共${body.rules.length}条规则。未命中的报修不会猜级别；版本变更仅影响新提交，不回算历史。理由：${body.reason}`,'确认替换优先级映射',{type:'warning'})}catch{pending.value=null;return}await send()}
async function retry(){if(unknown.value)await send();else await load()}
onMounted(load);onBeforeUnmount(()=>{alive=false;sequence++})
defineExpose({load})
</script>
<template><section class="card mapping-workbench"><header><h3>设施报修优先级映射</h3><p>只维护已获确认的“故障类型 × 影响范围 → 1—4级”组合。初始规则集为空；安全风险或区域无法安全使用始终为5级，不在此配置。映射版本不可覆盖，修改只作用于后续提交。</p></header><SBanner v-if="notice" type="success" :title="notice"/><SBanner v-if="error" type="error" :title="error"><SButton size="sm" :disabled="saving" @click="retry">{{unknown?'以原操作ID重试核对':'重试读取配置'}}</SButton></SBanner><p v-if="unknown" class="operation-id">原操作ID：{{pending?.operation_id}}</p><p>当前版本：{{version??'尚未读取'}}；规则{{rules.length}}条。{{rules.length?'禁用规则保留在版本历史中，不参与自动匹配。':'当前为空映射；非安全报修提交后将显示“未配置”，由管理员受理时核定。'}}</p><p v-if="loading" role="status">正在读取映射版本…</p><div class="rule-list"><article v-for="(rule,index) in rules" :key="index" class="mapping-rule"><label>故障类型<SInput v-model="rule.fault_type" maxlength="100" :disabled="busy" @update:model-value="update" /></label><label>影响范围<SInput v-model="rule.impact_scope" maxlength="100" :disabled="busy" @update:model-value="update" /></label><label>映射级别<SSelect v-model="rule.priority" :options="priorityOptions" :disabled="busy" @update:model-value="update" /></label><label class="enabled"><input v-model="rule.enabled" type="checkbox" :disabled="busy" @change="update"/> 启用</label><SButton size="sm" :disabled="busy" @click="removeRule(index)">从新版本移除</SButton></article></div><SButton :disabled="busy" @click="addRule">添加一条候选映射</SButton><label class="reason">本次版本变更理由<SInput v-model="reason" type="textarea" maxlength="1000" :disabled="busy" placeholder="说明映射依据与确认状态；不要把待确认候选写成团队已定" @update:model-value="update" /></label><SButton variant="primary" :disabled="busy||!dirty" :loading="saving" @click="save">保存新版本</SButton><p class="muted">此配置入口不代表映射值已获全组确认。请在理由中标明实际确认来源；未确认值不要启用。</p></section></template>
<style scoped>.mapping-workbench,.rule-list,.mapping-rule{display:grid;gap:14px;min-width:0}.mapping-workbench header p,.mapping-workbench>p{overflow-wrap:anywhere}.mapping-rule{grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(100px,.5fr) auto auto;align-items:end;padding:12px;border:1px solid var(--border);border-radius:var(--r-md);background:var(--surface-2)}.mapping-rule label,.reason{display:grid;gap:7px;min-width:0;font-size:var(--fs-caption)}.mapping-rule .enabled{display:flex;align-items:center;white-space:nowrap}.operation-id{overflow-wrap:anywhere}@media(max-width:800px){.mapping-rule{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.mapping-rule>.enabled{grid-column:1}.mapping-rule>button{grid-column:2;justify-self:end}}</style>
